_TYPE_TO_DRAFT = (0, 1, 2, 3, 3, 4, 5, 6, 7, 8, 9, 10)     # ChampionType -> ChampionDraft [sdk enums]

ME = {}


def me_init():
    """Fill ME once (round 1). Traces fuel (tag me) and one facts line."""
    f0 = fuel()
    try:
        c = cambc.me()
        t = int(c.champion_name())
        d = _TYPE_TO_DRAFT[t] if 0 <= t < len(_TYPE_TO_DRAFT) else -1
        flags = {"has_cc": False, "has_dash": False, "has_heal": False, "has_shield": False, "has_aoe": False,
                 "attack_reset": False, "camp_spell": False}
        spell_range = None
        for a in c.abilities():
            info = a.info()
            if info is None:
                continue
            cc, dash, dmg, aoe = a.is_cc(), a.is_dash(), a.is_damage(), a.is_aoe_damage()
            # [measured 14 Oct] Ryth's area stun is AoeDamage with duration=1 (is_cc() False); Marcella's stun is
            # AttackReset with enhanced_attack=True. Both count as CC here.
            flags["has_cc"] |= cc or (aoe and getattr(info, "duration", 0) > 0) or bool(getattr(info, "enhanced_attack", False))
            flags["has_dash"] |= dash
            flags["has_heal"] |= a.is_heal()
            flags["has_shield"] |= a.is_shield()
            flags["has_aoe"] |= aoe
            flags["attack_reset"] |= a.is_attack_reset()
            flags["camp_spell"] |= (dmg or aoe) and a.can_target_camps()
            r = getattr(info, "range", None)          # dash and self-shield ranges are not spell ranges
            if r is not None and not dash and not a.is_shield() and (spell_range is None or r > spell_range):
                spell_range = r
        ME.update(flags)
        ME.update({"id": d, "type": t, "prof": PROFILES.get(d, NEUTRAL), "strength": c.strength(),
                   "hp": c.max_health(), "range": c.attack_range(), "focus": c.focus(),
                   "spell_range": spell_range, "passive": int(c.passive())})
    except Exception as e:
        trace("me", err_text(e))
        if "prof" not in ME:
            ME["prof"] = NEUTRAL
    trace("me", f"fuel={f0 - fuel()}")
    if TRACE and "id" in ME:
        p = ME["prof"]
        trace("me", f"id={ME['id']} type={ME['type']} str={ME['strength']} hp={ME['hp']} range={ME['range']} "
                    f"focus={ME['focus']} spell_range={ME['spell_range']} passive={ME['passive']} "
                    + " ".join(k for k in ("has_cc", "has_dash", "has_heal", "has_shield", "has_aoe",
                                           "attack_reset", "camp_spell") if ME[k])
                    + " prof=" + ",".join(f"{p[k]}" for k in _KEYS) + f" item={int(p['item'])} gain={p['item_gain']}")

# ---- 30_world.py ----
"""World (play side): the round-1 boot, distance fields, groups and altars, roster slot, opening seed, movement.

Boot (once, round 1, ~1.5-3.5M): decode the draft memory (fallback: a minimal world from game_map, every side
contested), camp_groups() ONCE (~0.9M), fields F_alt (all altar rings), F_enemy (enemy spawn), F_me (my position;
rebuilt when I am > FME_MOVE tiles from its root or after a recall/death). Navigation uses goal fields per key
("g<h>" stand tiles of group h, "c<h>" its spawn tiles, "a<i>" altar i's ring, "home"), built on first use
(~280k at 80x80) and kept in a small cache. Nothing map-specific: everything comes from game_map at runtime.
"""

ROSTER = (9, 1, 0, 2, 6)    # draft ids in pick order: MUST match PICKS in 90_main's draft branch
CAMP_R = 3                  # every monster's attack range [measured A31]
FME_MOVE = 6                # rebuild F_me when I am more than this from its root (spec)
NAV_CACHE = 6               # goal fields kept (each ~31k memory, ~280k fuel to build at 80x80)
DIRS = tuple(V(dx, dy) for dx in (-1, 0, 1) for dy in (-1, 0, 1) if dx or dy)
G_HP = {}                   # CampType -> (base HP, base Strength) [sdk base_stats]


def fget(f, p):
    try:
        v = f.get(p)
    except Exception:
        return FAR
    return v if 0 <= v < FAR else FAR


def disk(c, r):
    b = Bitboard()
    b.draw_chebyshev(c, r)
    return b


G2G_K = 0.5                 # [tuned 15 Oct; PRICES guess 1.5] gems per gold at round 0


def g2g(r):
    """Gems per gold [guess, strat/PRICES.md G2G], falling linearly to 0 at round 2000."""
    return G2G_K * (2000 - r) / 2000


def clear_dmg(mons, S, k):
    """clear_damage (10_model) with a live Strength: (rounds, damage summed over the k bodies). mons: [(hp, str)]
    of the live monsters; monsters die one at a time, the most dangerous per HP first [measured A3, A4]."""
    r, dmg, kS = 0, 0, max(1.0, k * S)
    for hp, st in sorted(mons, key=lambda m: -m[1] / max(1, m[0])):
        r += -(-int(hp) // int(kS))
        dmg += st * (r - 1)
    return r, dmg


class Grp:
    __slots__ = ("h", "obj", "camps", "tiles", "anchor", "mons", "gems", "gold", "resp", "need", "side", "near",
                 "d_us", "d_them", "mi", "hp", "st", "until", "seen")


class World:
    def boot(self):
        f0 = fuel()
        self.me = me = cambc.me()
        self.Wm, self.Hm = game_map.width(), game_map.height()
        self.sp = game_map.spawn_region(Team.ALLY)
        self.esp = game_map.spawn_region(Team.ENEMY)
        self.sp0, self.esp0 = self.sp.positions()[0], self.esp.positions()[0]
        ab = game_map.altars()
        self.apos = ab.positions()
        terr = game_map.walls() | game_map.holes()
        d = None
        try:
            d = decode(cambc.draft_memory)
        except Exception as e:
            trace("boot", "decode " + err_text(e))
        self.d = d
        # groups: the only camp_groups() call
        self.G = {}
        self.order = []                 # group handles in camp_groups() order (draft-memory order)
        ct = Bitboard()
        for g in game_map.camp_groups():
            o = Grp()
            o.h, o.obj = int(g), g
            o.camps = g.camps()
            o.tiles = [c.spawn_position() for c in o.camps]
            o.anchor = o.tiles[0]
            mons = []
            for c in o.camps:
                k = int(c.kind())
                st = G_HP.get(k)
                if st is None:
                    b = c.base_stats()
                    st = G_HP[k] = (int(b.base_health), int(b.base_strength))
                mons.append(st)
            o.mons = mons
            o.gems, o.gold, o.resp = g.gem_value(), g.gold_value(), g.max_respawn_timer()
            o.need, o.side, o.near, o.d_us, o.d_them, o.mi = 1, 1, 255, 255, 255, 31
            o.hp = None                 # remembered live monsters [(hp, str)] (None: full)
            o.st, o.until, o.seen = "alive", 0, -1
            ct |= g.spawn_tiles()
            self.G[o.h] = o
            self.order.append(o.h)
        self.ctiles = ct
        self.blk_nav = terr | ab | self.esp | ct
        self.blk_dist = terr | self.esp            # F_me / F_enemy: altar and camp tiles passable (distances to them)
        nA = len(self.apos)
        self.aside = [1] * nA
        self.bank = 255
        if d:
            by = {h & 255: h for h in self.order}
            for i, rec in enumerate(d["groups"]):
                h = by.get(rec[0])
                if h is None:
                    continue
                o = self.G[h]
                o.side, o.need, o.near, o.d_us, o.d_them, o.mi = rec[1], rec[2], rec[4], rec[5], rec[6], min(i, 31)
            for i, a in enumerate(d["altars"][:nA]):
                self.aside[i] = a[0]
            self.bank = d["bank_altar"]
        else:
            S = max(1, len(cambc.champions(Team.ALLY)))
            for i, h in enumerate(self.order):
                o = self.G[h]
                o.mi = min(i, 31)
                o.need = bodies_needed(list(o.mons), S)
        self.idx = {self.G[h].mi: h for h in self.order if self.G[h].mi < 31}
        # fields
        self.nav = {}
        self.nav_keys = []
        rings = Bitboard()
        for a in self.apos:
            rings.draw_chebyshev(a, 1)
        rings &= ~self.blk_nav
        self.F_alt = DistanceField()
        self.F_alt.compute(self.blk_nav & ~rings, rings, Bitboard(), FAR - 1)
        self.F_enemy = DistanceField()
        self.F_enemy.compute(terr, self.esp, Bitboard(), FAR - 1)
        self.F_home = None
        if not d:
            self.F_home = DistanceField()
            self.F_home.compute(terr, self.sp, Bitboard(), FAR - 1)
            for h in self.order:
                o = self.G[h]
                o.d_us = min(255, fget(self.F_home, o.anchor))
                o.d_them = min(255, fget(self.F_enemy, o.anchor))
        if self.bank == 255 and nA:
            sp0 = self.sp.positions()[0]
            self.bank = min(range(nA), key=lambda i: sp0.chebyshev_distance(self.apos[i]))
        self.pos = me.position()
        self.build_fme(self.pos)
        self.slot_init()
        self.cast_init()
        trace("boot", f"mem={'ok' if d else 'none'} groups={len(self.order)} altars={nA} slot={self.slot} "
                      f"bank=A{self.bank} fuel={f0 - fuel()}")

    # ---- fields ----
    def build_fme(self, pos):
        """F_me from pos; gd/ad: walk distance to every group anchor / altar tile (stale until the next build)."""
        f = DistanceField()
        b = Bitboard()
        b.set(pos)
        f.compute(self.blk_dist, b, Bitboard(), FAR - 1)
        self.F_me, self.fme_root = f, pos
        self.gd = {h: fget(f, self.G[h].anchor) for h in self.order}
        self.ad = [fget(f, a) for a in self.apos]
        self.near6 = sorted(self.order, key=lambda h: self.gd[h])[:6]

    def home_field(self):
        if self.F_home is None:
            self.F_home = DistanceField()
            self.F_home.compute(game_map.walls() | game_map.holes(), self.sp, Bitboard(), FAR - 1)
        return self.F_home

    def goal(self, key):
        """Goal field for a nav key, built on first use, LRU-capped."""
        f = self.nav.get(key)
        if f is not None:
            return f
        k, blk = key[0], self.blk_nav
        if k == "g":
            r = max(1, ME.get("range", 1))
            roots = Bitboard()
            for t in self.G[int(key[1:])].tiles:
                roots.draw_chebyshev(t, r)
            roots &= ~blk
        elif k == "c":
            roots = Bitboard()
            for t in self.G[int(key[1:])].tiles:
                roots.set(t)
        elif k == "a":
            roots = disk(self.apos[int(key[1:])], 1) & ~blk
        else:
            roots = self.sp & ~blk
        f = DistanceField()
        f.compute(blk & ~roots, roots, Bitboard(), FAR - 1)
        self.nav[key] = f
        self.nav_keys.append(key)
        if len(self.nav_keys) > NAV_CACHE:
            self.nav.pop(self.nav_keys.pop(0), None)
        return f

    def walk_to(self, key, pos):
        """Exact walk if key's goal field is cached, else None."""
        f = self.nav.get(key)
        return None if f is None else fget(f, pos)

    # ---- roster slot ----
    def slot_init(self):
        """Roster slot = index of my draft id in the picked roster (ROSTER order, others after, by id)."""
        self.slot_of = {}
        ids = {}
        try:
            for c in cambc.champions(Team.ALLY):
                if c.is_visible():
                    t = int(c.champion_name())
                    ids[int(c)] = _TYPE_TO_DRAFT[t] if 0 <= t < len(_TYPE_TO_DRAFT) else t
        except Exception as e:
            trace("boot", "allies " + err_text(e))
        ids[int(self.me)] = ME.get("id", -1)
        ds = set(ids.values())
        roster = [p for p in ROSTER if p in ds] + sorted(p for p in ds if p not in ROSTER)
        self.roster = roster
        for hd, dd in ids.items():
            self.slot_of[hd] = roster.index(dd)
        mid = ME.get("id", -1)
        self.slot = min(4, roster.index(mid) if mid in roster else (ROSTER.index(mid) if mid in ROSTER else 4))

    def ally_slot(self, c):
        hd = int(c)
        s = self.slot_of.get(hd)
        if s is None:
            try:
                t = int(c.champion_name())
                dd = _TYPE_TO_DRAFT[t]
                s = ROSTER.index(dd) if dd in ROSTER else 4
            except Exception:
                s = 4
            self.slot_of[hd] = s
        return s

    # ---- abilities ----
    def cast_init(self):
        """Slots by use: camp damage, champion damage, CC (ME['has_cc'] rule), attack reset."""
        self.ab = []
        try:
            for a in self.me.abilities():
                info = a.info()
                if info is None:
                    continue
                aoe, dmg = a.is_aoe_damage(), a.is_damage()
                cc = a.is_cc() or (aoe and getattr(info, "duration", 0) > 0) or bool(getattr(info, "enhanced_attack", False))
                self.ab.append((a, (dmg or aoe) and a.can_target_camps(), (dmg or aoe or cc) and a.can_target_enemies(),
                                cc, a.is_attack_reset(), a.can_target_ground()))
        except Exception as e:
            trace("boot", "abilities " + err_text(e))

    def cast(self, target, camp):
        """One cast this turn on target (Unit) if a fitting slot is ready; False if none fired."""
        for a, on_camp, on_enemy, cc, reset, ground in self.ab:
            if (on_camp if camp else (on_enemy or (cc and not reset))) and not reset:
                try:
                    if not a.is_ready():
                        continue
                    if a.use(target):
                        return True
                except Exception:
                    try:
                        if ground and a.use(target.position()):
                            return True
                    except Exception:
                        pass
        return False

    def reset_attack(self, target):
        """Attack-reset slots (self-cast), then a second basic attack."""
        for a, _c, _e, _cc, reset, _g in self.ab:
            if reset:
                try:
                    if a.is_ready() and a.use(None):
                        self.me.attack(target)
                        return True
                except Exception:
                    pass
        return False

    # ---- movement ----
    def move(self, q):
        try:
            ok = self.me.move_absolute(q)
        except Exception:
            return False
        if ok:
            self.moved = True
        return ok

    def step_field(self, f, pos):
        """One step down field f: its optimal step, else the lowest finite neighbour below my value, else (on a
        wall tile of f, e.g. a camp spawn tile) the lowest finite neighbour. 'here' | 'moved' | 'blocked'."""
        v = fget(f, pos)
        if v == 0:
            return "here"
        dv = None
        if v < FAR:
            try:
                dv = f.next_move_from(pos)
            except Exception:
                dv = None
        self.last_step = f"v={v} dv={dv}"
        if dv is not None and self.move(pos + dv):
            self.nblock = 0
            return "moved"
        best = []
        nb = getattr(self, "nblock", 0)
        lim = v - 1 if nb < 1 else v if nb < 3 else v + 1     # sidestep after 1 blocked turn, uphill after 3
        for dv in DIRS:
            q = pos + dv
            u = fget(f, q)
            if u <= lim and u < FAR:
                best.append((u, q.x, q.y))
        best.sort()
        for u, x, y in best[:4]:
            if self.move(V(x, y)):
                self.nblock = 0
                return "moved"
        self.nblock = nb + 1
        return "blocked"

    def step_to(self, key, s):
        if not s.can_move:
            return "blocked"
        return self.step_field(self.goal(key), s.pos)

    def step_near(self, tiles, r, s):
        """Towards the tiles within r of tile(s) (a one-off compute_to, ~75k)."""
        if not s.can_move:
            return "blocked"
        blk = self.blk_nav | vision.champion_tiles()
        blk.set(s.pos, False)
        roots = Bitboard()
        for t in (tiles if isinstance(tiles, list) else (tiles,)):
            roots.draw_chebyshev(t, r)
        roots &= ~blk
        if roots.is_empty():
            return "blocked"
        dest = Bitboard()
        dest.set(s.pos)
        f = DistanceField()
        f.compute_to(blk & ~roots, roots, dest, Bitboard(), FAR - 1)
        return self.step_field(f, s.pos)

    def step_away(self, s, pts):
        """A step maximising the min Chebyshev distance to pts (out of camp range)."""
        if not s.can_move:
            return "blocked"
        pos = s.pos
        cand = []
        for dv in DIRS:
            q = pos + dv
            if not (0 <= q.x < self.Wm and 0 <= q.y < self.Hm) or self.blk_nav.is_set(q):
                continue
            cand.append((-min(q.chebyshev_distance(p) for p in pts), q.x, q.y))
        cand.sort()
        for _d, x, y in cand[:3]:
            if self.move(V(x, y)):
                return "moved"
        return "blocked"


WORLD = World()


def opening_seed(w):
    """Every champion computes the same list with no comms: groups on our side (0) and contested (1), ranked by
    value / (d_us + clear_rounds) with a generic champion (CHAMP_STR) and gold at G2G(1); a 1-body group fills
    one slot, a 2-body group two; slot i takes entry i. Seeds only the first choice."""
    rank = []
    for h in w.order:
        o = w.G[h]
        if o.side > 1 or o.d_us >= 255 or o.need > 2:
            continue
        hp = sum(m[0] for m in o.mons)
        cr = -(-hp // (CHAMP_STR * o.need))
        rank.append(((o.gems + g2g(1) * o.gold) / (o.d_us + cr + 1), -h, h, o.need))
    rank.sort(reverse=True)
    slots = []
    for _v, _n, h, need in rank:
        slots += [h] * need
    return slots[w.slot] if w.slot < len(slots) else None

# ---- 40_prices.py ----
"""Sense, price the six options (strat/PRICES.md) in team gems per round, choose with hysteresis, broadcast.

Option codes (shared byte, low 3 bits): 0 idle, 1 farm, 2 bank, 3 kill, 4 hold, 5 shop, 6 join, 7 dead; target in
the high 5 bits (group index in draft-memory order, altar index, enemy handle & 31, ally slot for join).
Byte 5: enemy sighting on our half, high nibble = altar index + 1 (0 none), low nibble = (round // 2) & 15 when seen;
a reader treats age >= SIGHT_AGE half-rounds as stale and clears it (~30 rounds, no writer needed to decay it).
"""

KEEP_HP = 0.4               # [guess] the hit body keeps >= 40 % of max HP (KEEP_FRAC)
HYST = 1.2                  # switch only when a new option beats the current one by 20 %
EXCL = 20                   # rounds an (option, target) is excluded after a timeout / failure
DENIAL = 24                 # [measured-ish] their farm rate 0.4 g/r x 60 rounds out (PRICES KILL)
THEIR_RATE = 0.4            # [guess] their gems per round per body (HOLD value 30 x 0.4)
P_NEAR = 0.5                # [guess] P(lose the bag) with an enemy within 8
DANGER_W = 0.2              # [guess] P(lose the bag) per unit of draft danger (cell value / 14)
SIGHT_AGE = 15              # half-rounds (~30 rounds) a sighting stays live
SHOP_RETURN = True          # [deviation] SHOP rounds include the walk back from spawn to where I am
SURVIVE = 0.6               # [tuned] k bodies are enough if the most-hit body keeps > 40 % of its current HP
WAIT_PARTNER = 15           # [guess] rounds added to a pair take while the partner is not committed
FUEL_FLOOR = 400_000        # after sensing: below this skip pricing, repeat the executor step
P_LOSE_MAX = 0.5            # [guess] FARM / BANK / KILL price 0 when the local Lanchester P(lose) exceeds this
FARM_PLOSE = 0.99           # [tuned] off: 0.65 (2 v 1) lost corners and interlock (we must contest the centre)
HOLD_PLOSE = 0.3            # [guess] HOLD needs a clearly safe altar
KILL_PLOSE = 0.45           # [tuned] fight only when locally stronger (0.5 = even; 0.99 lost 9 champions in kills)
DEATH_EXCL = 100            # rounds a death excludes its (option, target), and kill/hold after a kill/hold death
DEATH_MARK = 100            # rounds the team avoids a group an ally died farming (bytes 6-7)
OPT = ("idle", "farm", "bank", "kill", "hold", "shop", "join", "dead", "fall")
CODE = {o: i for i, o in enumerate(OPT)}
CLEAR_MEMO = {}


class Snap:
    __slots__ = ("r", "st", "alive", "recalling", "submitting", "can_move", "can_attack", "pos", "hp", "maxhp",
                 "bag", "gold", "S", "enemies", "allies", "live", "vis", "mem", "spawn", "near_e", "P", "walt", "edps", "plose")


def sense(w):
    me, r = w.me, cambc.round_number()
    s = Snap()
    s.r = r
    s.st = st = int(me.state())
    s.alive = bool(st & 1)
    s.recalling, s.submitting = bool(st & 2), bool(st & 4)
    s.can_move, s.can_attack = bool(st & 8), bool(st & 16)
    try:
        s.gold = me.gold_count()
    except Exception:
        s.gold = 0
    try:
        w.score = (cambc.global_submitted_gems(Team.ALLY), cambc.global_submitted_gems(Team.ENEMY))
    except Exception:
        pass
    s.mem = bytearray(8)
    try:
        cambc.shared_memory.read(0, s.mem)
    except Exception:
        pass
    s.enemies, s.allies, s.live, s.near_e = [], [], {}, 99
    if not s.alive:
        s.pos, s.hp, s.maxhp, s.bag, s.S, s.vis, s.spawn = w.pos, 0, 1, 0, 1, None, False
        return s
    s.pos = pos = me.position()
    s.hp, s.maxhp, s.bag, s.S = me.health(), me.max_health(), me.gem_count(), max(1.0, me.strength())
    s.spawn = w.sp.is_set(pos)
    for c in champs(Team.ENEMY):
        try:
            p = c.position()
            dd = pos.chebyshev_distance(p)
            s.enemies.append((c, p, c.health(), c.gem_count(), dd, c.strength()))
            if dd < s.near_e:
                s.near_e = dd
        except Exception:
            pass
    for c in champs(Team.ALLY):
        try:
            p = c.position()
            if p != pos:
                s.allies.append((c, p, c.health(), c.strength()))
        except Exception:
            pass
    s.vis = None
    hs = list(w.near6)
    cur = w.cur
    if cur[0] == "farm" and cur[1] not in hs and cur[1] in w.G:
        hs.append(cur[1])
    for h in hs:                                # boot Camp objects: no vision.camps() (~540k on 2.1.4)
        o = w.G[h]
        if o.anchor.chebyshev_distance(pos) > 11:
            continue
        lv = []
        for c, t in zip(o.camps, o.tiles):
            try:
                if c.is_visible():
                    lv.append((c, c.health(), t, G_HP[int(c.kind())][1]))
            except Exception:
                pass
        if lv:
            s.live[h] = lv
    return s


def champs(team):
    """vision.champions, with a per-tile fallback when the list read raises (docs/HANDOFF.md)."""
    try:
        return vision.champions(team)
    except Exception:
        out = []
        try:
            for p in vision.champion_tiles(team).positions():
                try:
                    out.append(vision.champion_at(p))
                except Exception:
                    pass
        except Exception:
            pass
        return out


def visible(w, s, o):
    if s.vis is None:
        s.vis = vision.visible_tiles()
    return not (s.vis & o.obj.spawn_tiles()).is_empty()


def update_groups(w, s, hs):
    """Refresh the remembered state of groups hs from what I see (state() only when no live camp is visible)."""
    for h in hs:
        o = w.G[h]
        lv = s.live.get(h)
        if lv:
            o.st, o.seen = "alive", s.r
            cur = [(hp, st) for _c, hp, _p, st in lv]
            if len(lv) < len(o.camps) and not visible_all(w, s, o):
                cur += o.mons[:len(o.camps) - len(lv)]        # unseen camps: assume alive, full HP
            o.hp = cur
            continue
        if o.seen == s.r or not visible(w, s, o):
            continue
        try:
            gs = o.obj.state()
        except Exception:
            continue
        o.seen = s.r
        if isinstance(gs, game_map.CampGroupRewardAvailable):
            o.st, o.hp = "reward", []
        elif isinstance(gs, game_map.CampGroupRespawning):
            o.st, o.hp = "resp", None
            try:
                o.until = s.r + int(gs.cooldown) + 1
            except Exception:
                o.until = s.r + o.resp
        else:
            o.st = "alive"


def visible_all(w, s, o):
    if s.vis is None:
        s.vis = vision.visible_tiles()
    t = o.obj.spawn_tiles()
    return (s.vis & t) == t


def claims(w, s):
    """{group handle: allies broadcasting farm/join on it}, {slot: (opt, tgt)}."""
    cl, by = {}, {}
    for k in range(5):
        if k == w.slot:
            continue
        b = s.mem[k]
        op, tg = b & 7, b >> 3
        by[k] = (op, tg)
        if op == 1 and tg in w.idx:
            h = w.idx[tg]
            cl[h] = cl.get(h, 0) + 1
    return cl, by


def danger_p(w, s):
    if s.near_e <= 8:
        return P_NEAR
    d = w.d
    if d and d.get("danger"):
        v = d["danger"][(s.pos.y * GRID // w.Hm) * GRID + s.pos.x * GRID // w.Wm]
        if v < 15:
            return DANGER_W * v / 14
    return 0.0


def farm_price(w, s, h, bodies, walk):
    o = w.G[h]
    if o.st == "resp" and o.until > s.r:
        return 0.0
    prof = ME["prof"]
    value = o.gems + g2g(s.r) * o.gold * prof["gold"]
    if o.st == "reward":
        return value / max(1, bodies) / (walk + 5)
    if o.hp is None:                            # full HP: cached per (group, bodies, my Strength)
        key = (h, bodies, s.S)
        cd = CLEAR_MEMO.get(key)
        if cd is None:
            if len(CLEAR_MEMO) > 400:
                CLEAR_MEMO.clear()
            cd = CLEAR_MEMO[key] = clear_dmg(o.mons, s.S, bodies)
        clear, dmg = cd
    else:
        mons = [m for m in o.hp if m[0] > 0]
        if not mons:
            return value / max(1, bodies) / (walk + 5)
        clear, dmg = clear_dmg(mons, s.S, bodies)
    per = dmg / bodies + s.edps * min(clear + 5, 10)    # [tuned] + visible enemies hitting me (within 4)
    if per >= s.hp:
        return 0.0                                  # [deviation] certain death is not a price
    miss = bodies - 1 - w.claims.get(h, 0)
    if miss > 0:
        walk += WAIT_PARTNER * miss                 # [guess] partners not committed yet
    risk = s.bag if s.hp - per < KEEP_HP * s.maxhp else s.P * s.bag   # [tuned] bag exposure (danger_p)
    detour = 0
    if o.near < len(w.apos):
        detour = max(0, o.anchor.chebyshev_distance(w.apos[o.near]) - s.walt)
    return value / bodies / (walk + clear + 5 + detour) - risk


def need_k(w, s, h, c):
    """Smallest k >= 1 + c (claimants + me), at most the team, whose most-hit body keeps KEEP_HP (live clear model:
    my HP and Strength, monsters' remembered HP); None if no team size does. Pair takes price with this k and pay
    WAIT_PARTNER per body not yet committed, so the first champion claims and the second sees one claimant."""
    o = w.G[h]
    if o.st != "alive":
        return 1 + c
    mons = o.mons if o.hp is None else [m for m in o.hp if m[0] > 0]
    if not mons:
        return 1 + c
    T = max(1, len(w.roster))
    floor = s.hp * SURVIVE                      # survival, as FARM's own zero rule (KEEP_HP stays a risk term)
    for k in range(1 + c, T + 1):
        key = (h, k, s.S) if o.hp is None else None
        cd = CLEAR_MEMO.get(key) if key else None
        if cd is None:
            cd = clear_dmg(mons, s.S, k)
            if key:
                CLEAR_MEMO[key] = cd
        if cd[1] / k + s.edps * min(cd[0] + 5, 10) <= floor:
            return k
    return None


def lanchester(s, e_pos):
    """P(we lose) from sum(hp x str) within 5 of the target on each side [guess, PRICES S2]."""
    us = s.hp * s.S if s.pos.chebyshev_distance(e_pos) <= 5 else 0
    for _c, p, hp, st in s.allies:
        if p.chebyshev_distance(e_pos) <= 5:
            us += hp * st
    th = 0
    for _c, p, hp, _b, _d, st in s.enemies:
        if p.chebyshev_distance(e_pos) <= 5:
            th += hp * st
    return th / max(1.0, us + th)


def price_all(w, s, cl, by):
    """[(price, option, target)] for every option this turn (multipliers applied)."""
    prof, r = ME["prof"], s.r
    out = []
    # FARM over the ~6 nearest groups by F_me (+ the current target, + cleared groups seen)
    cand = list(w.near6)
    cur = w.cur
    if cur[0] in ("farm", "join") and cur[1] is not None:
        hh = cur[1] if cur[0] == "farm" else None
        if hh is not None and hh not in cand:
            cand.append(hh)
    for h in s.live:
        if h in w.G and h not in cand and len(cand) < 9:
            cand.append(h)
    s.P = danger_p(w, s)
    s.edps = sum(e[5] for e in s.enemies if e[4] <= 4)
    s.walt = fget(w.F_alt, s.pos)
    s.plose = lanchester(s, s.pos) if s.enemies else 0.0
    dead_g = None
    if s.mem[6] and (((r // 8) - s.mem[7]) & 255) * 8 < DEATH_MARK:
        dead_g = w.idx.get(s.mem[6] - 1)
    update_groups(w, s, cand)
    for h in cand:
        o = w.G[h]
        c = cl.get(h, 0)
        k = need_k(w, s, h, c)                  # bodies the live clear model needs, me + c claimants at least
        if k is None or (c == 0 and k >= 2 and r < w.pair_until):
            continue
        # [deviation] spec: "claimants >= bodies needed prices 0 for me". Measured 15 Oct (bench fix7/fix8 vs fix6):
        # that gate, even for solo groups only, lost rows A and raised elkring deaths 5 -> 17-19 (elks taken by too
        # few bodies). Extra bodies instead price value / bodies, which already makes crowding unattractive.
        if h == dead_g or (s.plose > FARM_PLOSE and s.near_e <= 5):
            continue                            # an ally died farming it recently, or outnumbered here
        wk = w.walk_to(f"g{h}", s.pos)
        if wk is None or wk >= FAR:
            wk = w.gd.get(h, FAR)
        if wk >= FAR:
            continue
        p = farm_price(w, s, h, k, wk) * prof["farm"]
        out.append((p, "farm", h))
    # BANK
    if s.bag > 0 and w.apos:
        order = sorted(range(len(w.apos)), key=lambda i: w.ad[i])
        a = order[0]
        if w.aside[a] == 2 and w.bank < len(w.apos):
            a = w.bank
        wk = w.walk_to(f"a{a}", s.pos)
        if wk is None or wk >= FAR:
            wk = max(0, w.ad[a] - 1)
        if wk < FAR and not (s.near_e <= 4 and s.plose > P_LOSE_MAX):
            P = s.P
            # [deviation] the risk of holding the bag is ADDED to BANK (PRICES: "at bag >= 20 with an enemy
            # within 8, risk dominates and BANK wins"); subtracting it would stop every bank near an enemy.
            out.append((s.bag * (1 + P) / (wk + max(1, -(-s.bag // 10))) * prof["bank"], "bank", a))
    # KILL: closable targets only
    reach = ME.get("range", 1) + 1 + (2 if ME.get("has_dash") else 0)
    for c, p, hp, bag, dd, st in (s.enemies if r >= w.kh_until else ()):
        try:
            chan = c.is_submitting_gems() or c.is_recalling()
            stun = (not chan) and dd <= reach + 3 and c.buffs().has_stun()
        except Exception:
            chan = stun = False
        if not (chan or stun or dd <= reach):
            continue
        value = bag + 50 * g2g(r) + DENIAL
        rounds = max(0, dd - ME.get("range", 1)) + -(-int(hp) // int(s.S))
        pl = lanchester(s, p)
        if pl > KILL_PLOSE:
            continue
        risk = pl * (s.bag + 60 * THEIR_RATE)
        # [deviation] (value - risk) / rounds: PRICES' value / rounds - risk subtracts gems from gems/round, so an
        # even fight never priced and farmers took hits without answering
        out.append(((value - risk) / max(1, rounds) * prof["kill"], "kill", int(c)))
    # HOLD: contested altar, stun or lock gold, a fresh sighting there
    sb = s.mem[5]
    if sb >> 4:
        a = (sb >> 4) - 1
        age = ((r // 2) - (sb & 15)) & 15
        # spec: stun OR lock gold; we never buy or place locks, so only a stun counts [deviation]
        if age < SIGHT_AGE and a < len(w.apos) and w.aside[a] == 1 and ME.get("has_cc") and                 r >= w.kh_until and s.plose <= HOLD_PLOSE:
            wk = w.walk_to(f"a{a}", s.pos)
            if wk is None or wk >= FAR:
                wk = max(0, w.ad[a] - 1)
            out.append((30 * THEIR_RATE / (wk + 30) * prof["hold"], "hold", a))
    # SHOP
    item = prof["item"]
    try:
        cost = item.cost()
    except Exception:
        cost = 30
    if s.gold >= cost:
        n = s.gold // cost
        rounds = 1 if s.spawn else 6
        if SHOP_RETURN and not s.spawn:
            rounds += fget(w.home_field(), s.pos) if w.F_home is not None else 20
        out.append((g2g(r) * n * cost / rounds * prof["shop"], "shop", 0))
    # JOIN: an ally farming a group that needs >= 2
    for k, (op, tg) in by.items():
        if op != 1 or tg not in w.idx:
            continue
        h = w.idx[tg]
        o = w.G[h]
        if o.need < 2:
            continue
        wk = w.gd.get(h, FAR)
        if wk >= FAR:
            continue
        if min(t.chebyshev_distance(s.pos) for t in o.tiles) <= 4:
            continue                            # there: FARM(g) prices itself
        b = cl.get(h, 1)
        lo = farm_price(w, s, h, b, wk) * b if b >= o.need else 0.0
        gain = farm_price(w, s, h, b + 1, wk) * (b + 1) - max(0.0, lo)
        if gain > 0:
            out.append((gain / max(1, wk) * prof["join"], "join", k))
    return out


def choose(w, s):
    """Argmax with hysteresis; returns True when the choice changed."""
    cl, by = claims(w, s)
    w.claims = cl
    ps = price_all(w, s, cl, by)
    r = s.r
    ps = [t for t in ps if w.excl.get((t[1], t[2]), -1) <= r]
    ps.sort(key=lambda t: -t[0])
    cur = w.cur
    curp = None
    for t in ps:
        if t[1] == cur[0] and t[2] == cur[1]:
            curp = t[0]
            break
    best = ps[0] if ps else (0.0, "fall", None)
    if best[0] <= 0:
        best = (0.0, "fall", None)
    keep = (curp is not None and curp > 0 and w.status == "going" and best[0] <= curp * HYST) or \
           (cur[0] == "fall" and best[1] == "fall" and w.status == "going")
    if keep:
        return False
    new = (best[1], best[2])
    if new == cur and w.status == "going":
        return False
    w.set_cur(new, r, s)
    if TRACE:
        t2 = ps[1] if len(ps) > 1 else (0.0, "-", None)
        trace("choice", f"{new[0]} {tname(w, new[0], new[1])} {best[0]:.2f} | {t2[1]} {tname(w, t2[1], t2[2])} "
                        f"{t2[0]:.2f} cur={curp if curp is None else round(curp, 2)}")
    return True


def tname(w, op, tg):
    if tg is None:
        return "-"
    if op == "farm":
        o = w.G.get(tg)
        return f"g{tg}@{o.anchor.x},{o.anchor.y}" if o else str(tg)
    if op in ("bank", "hold"):
        return f"A{tg}"
    return str(tg)


def tbits(w, op, tg):
    if tg is None:
        return 0
    if op == "farm":
        return w.G[tg].mi if tg in w.G else 31
    return int(tg) & 31


def broadcast(w, s, code):
    """My byte (slot) when it changed; byte 5 sighting on our half."""
    b = code | (tbits(w, OPT[code], w.cur[1]) << 3 if 0 < code < 7 else 0)
    if b != w.sent:
        try:
            cambc.shared_memory[w.slot] = b
            w.sent = b
        except Exception:
            pass
    if not s.alive:
        return
    sb = s.mem[5]
    if sb >> 4 and (((s.r // 2) - (sb & 15)) & 15) >= SIGHT_AGE:
        try:
            cambc.shared_memory[5] = 0
        except Exception:
            pass
    if s.enemies and w.apos:
        hf = w.F_home
        for _c, p, _hp, _b, _d, _st in s.enemies:
            de = fget(w.F_enemy, p)
            ours = (fget(hf, p) < de) if hf is not None else                 p.chebyshev_distance(w.sp0) < p.chebyshev_distance(w.esp0)
            if ours:
                a = min(range(len(w.apos)), key=lambda i: p.chebyshev_distance(w.apos[i]))
                if a < 15:
                    try:
                        cambc.shared_memory[5] = (a + 1) << 4 | ((s.r // 2) & 15)
                    except Exception:
                        pass
                break

# ---- 50_exec.py ----
"""Executors: one step of the current (option, target) per turn -> "going" | "done" | "failed".

No stored intent beyond (option, target, started, deadline, exclusions) plus per-executor progress counters.
Timeout = walk estimate + 10 rounds, plus the option's own work (clear + capture for farm, the channel for bank,
30 rounds for hold); a timeout is a failure and excludes (option, target) for EXCL rounds.
"""


def _set_cur(self, new, r, s):
    op, tg = new
    self.cur, self.started, self.status = new, r, "going"
    self.kd, self.kn, self.arrived = 99, 0, None
    self.lastbag, self.lastgold = s.bag, s.gold
    walk, work = 0, 0
    if op == "farm" and tg in self.G:
        walk = self.gd.get(tg, 40)
        o = self.G[tg]
        mons = [m for m in (o.hp if o.hp is not None else o.mons) if m[0] > 0]
        work = (clear_dmg(mons, s.S, max(1, o.need))[0] if mons else 0) + 8
        if o.need >= 2:
            work += 10                          # waiting for the partner
    elif op in ("bank", "hold") and tg is not None and tg < len(self.ad):
        walk = self.ad[tg]
        work = max(1, -(-s.bag // 10)) + 2 if op == "bank" else 30
    elif op == "shop":
        work = 8
    elif op == "join" and tg is not None:
        walk = 20
    elif op == "kill":
        walk = 6
    elif op == "fall":
        walk = 15
    self.deadline = r + min(walk, 150) + 10 + work


World.set_cur = _set_cur


RETREAT_HP = 0.6            # [guess] fallback retreats from enemies within 4 below this HP fraction


def in_camp_range(s, w):
    pts = []
    for h, lv in s.live.items():
        for _c, _hp, p, st in lv:
            if st > 0 and p.chebyshev_distance(s.pos) <= CAMP_R:
                pts.append(p)
    return pts


def safe_recall(w, s):
    """Recall unless an enemy is within 3 or a live camp within range 3 (its hit would cancel it): then step out."""
    if s.recalling:
        return "going"
    pts = in_camp_range(s, w)
    if pts:
        w.step_away(s, pts)
        return "going"
    if s.near_e <= 3:
        w.step_to("home", s)
        return "going"
    try:
        w.me.recall()
        w.recall_r = s.r
    except Exception:
        w.step_to("home", s)
    return "going"


def partners_near(w, s, h):
    """Visible allies within 4 of the group's camps that broadcast farm on it, or join."""
    n = 0
    o = w.G[h]
    for c, p, _hp, _st in s.allies:
        if min(t.chebyshev_distance(p) for t in o.tiles) <= 4:
            k = w.ally_slot(c)
            b = s.mem[k] if k < 5 else 0
            if ((b & 7) == 1 and (b >> 3) == o.mi) or (b & 7) == 6:
                n += 1
    return n


def live_ok(w, s, h, k):
    """k bodies (Strength like mine) clear h with the most-hit body keeping KEEP_HP (live clear model)."""
    o = w.G[h]
    mons = [m for m in (o.hp if o.hp is not None else o.mons) if m[0] > 0]
    if not mons:
        return True
    return clear_dmg(mons, s.S, k)[1] / k <= s.hp * SURVIVE


def exec_farm(w, s, h):
    o = w.G[h]
    lv = s.live.get(h)
    if lv:
        tgt = [(hp, i) for i, (_c, hp, p, _st) in enumerate(lv) if p.chebyshev_distance(s.pos) <= ME.get("range", 1)]
        hurt = any(hp < w.G_maxhp(c) for c, hp, _p, _st in lv)
        if o.need >= 2 and not hurt and not live_ok(w, s, h, 1 + partners_near(w, s, h)):
            # pair take: wait (monsters are friendly until hit) near the group for the partner
            near = min(p.chebyshev_distance(s.pos) for _c, _hp, p, _st in lv)
            if near > 4:
                w.step_to(f"g{h}", s)
            w.waiting = True
            return "going"
        if tgt and s.can_attack:
            tgt.sort()
            c = lv[tgt[0][1]][0]
            try:
                w.me.attack(c)
                w.attacked = True
                w.reset_attack(c)
            except Exception:
                pass
            if s.st & 0x800:                     # CAN_CAST
                w.cast(c, True)
            return "going"
        if tgt:
            w.attacked = True                   # in range, attack spent this turn
            return "going"
        if len(lv) < len(o.tiles) and w.walk_to(f"g{h}", s.pos) == 0:
            w.step_near([p for _c, _hp, p, _st in lv], ME.get("range", 1), s)    # next to a dead camp only
        else:
            w.step_to(f"g{h}", s)
        return "going"
    # no live camp of h in vision
    if visible(w, s, o):
        if o.seen != s.r:
            update_groups(w, s, [h])
        if o.st == "resp":
            return "done"
        if o.st == "reward":
            onspawn = any(t == s.pos for t in o.tiles)
            if onspawn:
                w.capt = True
                if s.bag > w.lastbag or s.gold > w.lastgold:
                    o.st, o.until = "resp", s.r + o.resp
                    return "done"
                return "going"
            if w.step_to(f"c{h}", s) == "blocked" and s.can_move:
                w.step_near(o.anchor, 0, s)
            return "going"
    if s.bag > w.lastbag and w.capt:
        o.st, o.until = "resp", s.r + o.resp
        return "done"
    w.step_to(f"g{h}", s)
    return "going"


def _maxhp(self, c):
    try:
        return G_HP[int(c.kind())][0]
    except Exception:
        return 1e9


World.G_maxhp = _maxhp


def exec_bank(w, s, a):
    if s.submitting:
        return "going"
    if s.bag == 0:
        return "done"
    ap = w.apos[a]
    if s.pos.chebyshev_distance(ap) <= 1:
        if s.near_e <= 3 and s.bag > 10:
            return "failed"                     # [tuned] no multi-turn channel next to an enemy (8 bank deaths)
        try:
            w.me.submit_gems(ap)
            return "going"
        except Exception:
            return "failed"
    if w.step_to(f"a{a}", s) == "blocked" and w.walk_to(f"a{a}", s.pos) >= FAR:
        return "failed"
    return "going"


def find_enemy(s, hd):
    for e in s.enemies:
        if int(e[0]) == hd:
            return e
    return None


def exec_kill(w, s, hd):
    e = find_enemy(s, hd)
    if e is None:
        return "failed"
    c, p, hp, _b, dd, _st = e
    if hp <= 0:
        return "done"
    rng = ME.get("range", 1)
    if dd <= rng:
        w.attacked = True
        if s.can_attack:
            try:
                w.me.attack(c)
                w.reset_attack(c)
            except Exception:
                pass
        if s.st & 0x800:
            w.cast(c, False)
        return "going"
    if dd >= w.kd:
        w.kn += 1
        if w.kn >= 3:
            return "failed"
    else:
        w.kn = 0
    w.kd = dd
    if s.st & 0x800:
        w.cast(c, False)                        # dashes and ranged spells close the gap
    w.step_near(p, rng, s)
    return "going"


def exec_hold(w, s, a):
    ap = w.apos[a]
    if s.pos.chebyshev_distance(ap) > 1:
        w.step_to(f"a{a}", s)
        return "going"
    if w.arrived is None:
        w.arrived = s.r
    w.capt = True                               # deliberate stand
    for c, p, hp, _b, dd, _st in s.enemies:
        try:
            chan = c.is_submitting_gems()
        except Exception:
            chan = False
        if chan:
            if s.st & 0x800:
                for ab, _oc, _oe, cc, _rs, _g in w.ab:
                    if cc:
                        try:
                            if ab.is_ready() and ab.use(c):
                                break
                        except Exception:
                            pass
            if dd <= ME.get("range", 1) and s.can_attack:
                try:
                    w.me.attack(c)
                    w.attacked = True
                except Exception:
                    pass
            break
    return "done" if s.r - w.arrived >= 30 else "going"


def buy_all(w, s):
    item = ME["prof"]["item"]
    n = 0
    try:
        while n < 10 and w.me.can_buy(item):
            w.me.buy(item)
            n += 1
    except Exception:
        pass
    return n


def exec_shop(w, s, _t):
    if s.spawn or not s.alive:
        buy_all(w, s)
        return "done"
    return safe_recall(w, s)


def exec_join(w, s, k):
    b = s.mem[k] if k < 5 else 0
    if (b & 7) != 1 or (b >> 3) not in w.idx:
        return "failed"
    h = w.idx[b >> 3]
    if min(t.chebyshev_distance(s.pos) for t in w.G[h].tiles) <= 4:
        return "done"
    w.step_to(f"g{h}", s)
    return "going"


def exec_fall(w, s, _t):
    near = [e for e in s.enemies if e[4] <= 4]
    if near and not s.spawn:
        allies = sum(1 for a in s.allies if a[1].chebyshev_distance(s.pos) <= 4)
        if len(near) > allies + 1 or s.hp < RETREAT_HP * s.maxhp:
            if s.near_e <= 3:                   # retreat: out of their reach first, recall once clear
                w.step_away(s, [e[1] for e in near])
                return "going"
            return safe_recall(w, s)
    if (s.bag > 0 or s.hp < KEEP_HP * s.maxhp) and not s.spawn:
        return safe_recall(w, s)
    if s.spawn and s.hp < s.maxhp:
        w.capt = True                           # healing on spawn
        return "going"
    if w.bank < len(w.apos):
        w.step_to(f"a{w.bank}", s)
    return "going"


EXEC = {"farm": exec_farm, "bank": exec_bank, "kill": exec_kill, "hold": exec_hold, "shop": exec_shop,
        "join": exec_join, "fall": exec_fall}

# ---- 90_main.py ----
"""Entry. Draft: pick on every draft turn (Varg, Vesper Vale, Ryth, Vendetta, Marcella), run the model stages under
the fuel guard, spilling to later draft turns; encode to draft memory. Play: decode once, trace the summary on
round 1, then do nothing.

Draft memory: submit() raises once pick() was called in the same turn (engine error 18 on later turns; on turn 1
"Memory access requires the owning team's input boundary") [measured 14 Oct, bots/_bench]. So turn 1 picks,
then models and encodes; every later turn submits the bytes encoded so far (~30k fuel) immediately before its
pick, then continues the model. The champions read the last submit [measured]. Work done on the last draft turn
is never submitted, so every stage must finish before it.
"""

if cambc.is_draft():
    # ChampionDraft values [sdk]: RYTH 0, VESPER_VALE 1, VARG 9, MARCELLA 6, VENDETTA 2; others as backup.
    # Three-pick maps take the first three (Varg, Vesper, Ryth).
    PICKS = (9, 1, 0, 2, 6)
    BACKUP = PICKS + tuple(d for d in range(11) if d not in PICKS)
    LATE_RESERVE = 700_000      # later draft turns: the pick and submit are done first; keep room for encode

    def do_pick():
        try:
            ours = [int(p) for p in cambc.draft.current_draft(Team.ALLY)]
            p = next((d for d in BACKUP if d not in ours), PICKS[0])
            cambc.draft.pick(p)
            return p
        except Exception as e:
            trace("draft", "pick " + err_text(e))
            return None

    def draft_main():
        try:
            _TAG[0] = f"{'AB'[cambc._bc.my_team()]}|draft"
        except Exception:
            pass
        dm = None
        data = None
        turn = 0
        while True:
            turn += 1
            f_start = fuel()
            sub = "-"
            if data is not None:
                try:
                    cambc.draft_memory.submit(data)            # before the pick (see the docstring)
                    sub = str(len(data))
                except Exception as e:
                    sub = err_text(e)
            picked = do_pick()
            ran = touched = []
            try:
                if dm is None:
                    dm = DraftModel()
                    if turn == 1 and TRACE:
                        for line in bodies_table(5):
                            trace("bodies", line)
                ran, touched = dm.run(turn, DRAFT_RESERVE if turn == 1 else LATE_RESERVE)
                if ran or data is None:
                    f0 = fuel()
                    data = dm.encode()
                    trace("stage", f"encode turn={turn} fuel={f0 - fuel()} bytes={len(data)}")
            except Exception as e:
                trace("draft", err_text(e))
            trace("draft", f"turn={turn} start={f_start} picked={picked} submitted={sub} ran={','.join(ran)} worked={','.join(touched)} "
                           f"pending={','.join(dm.stages) if dm else '?'} used={f_start - fuel()} left={fuel()}")
            cambc.end_turn()

    draft_main()
else:
    OSC_N = 16                                    # alternating moves between two tiles before `osc` fires

    def turn(w):
        fa = fuel()
        s = sense(w)
        w.ph[0] = max(w.ph[0], fa - fuel())
        r = s.r
        flags = (w.attacked, w.capt, w.waiting)
        w.attacked = w.capt = w.waiting = w.moved = False
        if not s.alive:
            w.act[6] += 1
            if w.was_alive:
                trace("death", f"bag={w.bag_alive} pos={w.pos.x},{w.pos.y} hp={w.hp_alive:.0f} cur={w.cur[0]} "
                               f"{tname(w, w.cur[0], w.cur[1])} enemies={w.ne_alive}")
                w.was_alive = False
                op, tg = w.cur
                w.excl[w.cur] = r + DEATH_EXCL            # no re-entry where I just died
                if op in ("kill", "hold"):
                    w.kh_until = r + DEATH_EXCL
                if op == "farm" and tg in w.G and w.G[tg].mi < 31:
                    try:                                  # team marker: avoid this group (bytes 6-7)
                        cambc.shared_memory[6] = w.G[tg].mi + 1
                        cambc.shared_memory[7] = (r // 8) & 255
                    except Exception:
                        pass
                w.cur, w.status = ("dead", None), "done"
            if s.gold >= 30:
                buy_all(w, s)                     # dead champions may shop [rules]
            broadcast(w, s, 7)
            return
        if not w.was_alive:
            w.was_alive = True
            w.status = "done"
            w.build_fme(s.pos)
        elif s.pos.chebyshev_distance(w.fme_root) > FME_MOVE:
            w.build_fme(s.pos)                    # also after a recall (the jump is > 6)
        # stuck guard: same tile, last turn neither capturing, channelling, attacking nor dead
        exempt = flags[0] or flags[1] or s.recalling or s.submitting
        if s.pos == w.pos and not exempt:
            w.same += 1
            w.stay += 1
        else:
            w.same = w.stay = 0
        if w.stay == 30:
            trace("stay", f"{s.pos.x},{s.pos.y} {w.cur[0]} {tname(w, w.cur[0], w.cur[1])} wait={int(flags[2])}")
        # oscillation: back and forth between the same two tiles (moves that return to the previous distinct tile)
        if exempt:
            w.osc = 0
        elif s.pos != w.pos:
            w.osc = w.osc + 1 if s.pos == w.p2 else 0
            w.p2 = w.pos
        osc_hit = False
        if w.osc >= OSC_N and not w.osc_fired:
            w.osc_fired = osc_hit = True
            ex = ",".join(f"{k[0]}:{tname(w, k[0], k[1])}" for k, v in w.excl.items() if v > r)
            trace("osc", f"{s.pos.x},{s.pos.y}<->{w.p2.x},{w.p2.y} {w.cur[0]} {tname(w, w.cur[0], w.cur[1])} "
                         f"wait={int(flags[2])} same={w.same} excl={ex or '-'} pair_until={w.pair_until}")
        elif w.osc == 0:
            w.osc_fired = False
        w.pos, w.bag_alive, w.hp_alive = s.pos, s.bag, s.hp
        w.ne_alive = len(s.enemies)
        if w.same >= 20 and w.status == "going":
            trace("exec", f"{w.cur[0]} {tname(w, w.cur[0], w.cur[1])} failed stuck")
            w.excl[w.cur] = r + EXCL
            if flags[2]:
                w.pair_until = r + 2 * EXCL       # no partner came: no un-partnered pair takes for a while
            w.status = "failed"
            w.same = 0
        if w.status == "going" and r > w.deadline and not (s.recalling or s.submitting):
            trace("exec", f"{w.cur[0]} {tname(w, w.cur[0], w.cur[1])} failed timeout")
            w.excl[w.cur] = r + EXCL
            w.status = "failed"
        for _k in range(2):
            if not (s.recalling or s.submitting) and fuel() > FUEL_FLOOR and r > w.seed_until:
                fb = fuel()
                choose(w, s)
                w.ph[1] = max(w.ph[1], fb - fuel())
            op, tg = w.cur
            fb = fuel()
            fn = EXEC.get(op)
            if fn is None:
                break
            st = fn(w, s, tg)
            w.ph[2] = max(w.ph[2], fb - fuel())
            if st == "going":
                w.status = st
                break
            trace("exec", f"{op} {tname(w, op, tg)} {st}")
            if st == "failed":
                w.excl[w.cur] = r + EXCL
            w.status = st
            if fuel() < 900_000:
                break
        broadcast(w, s, CODE.get(w.cur[0], 0) if w.cur[0] in CODE else 0)
        k = 3 if s.recalling or s.submitting else 1 if w.attacked else 2 if w.capt else 4 if w.waiting else             0 if w.moved else 5
        w.act[k] += 1
        w.idle = w.idle + 1 if k == 5 else 0
        if w.idle == 4 and TRACE:
            op, tg = w.cur
            x = ""
            if op == "farm" and tg in w.G:
                o = w.G[tg]
                x = (f"st={o.st} live={len(s.live.get(tg, ()))} vis={int(visible(w, s, o))} "
                     f"d={min(t.chebyshev_distance(s.pos) for t in o.tiles)} walk={w.walk_to(f'g{tg}', s.pos)} "
                     f"canmove={int(s.can_move)}")
            trace("idle", f"{op} {tname(w, op, tg)} {x} step={getattr(w, 'last_step', '-')} "
                          f"occ={vision.champion_tiles().count()}")
            w.last_step = "-"
        if w.F_home is None and fuel() > 1_200_000:
            w.home_field()

    def play_main():
        base_init()
        w = WORLD
        w.cur, w.status, w.excl, w.sent, w.started, w.deadline = ("idle", None), "done", {}, -1, 0, 0
        w.claims, w.was_alive, w.same, w.stay, w.seed_until = {}, True, 0, 0, 0
        w.attacked = w.capt = w.waiting = False
        w.bag_alive, w.hp_alive, w.ne_alive, w.kd, w.kn, w.arrived = 0, 0, 0, 99, 0, None
        w.lastbag = w.lastgold = 0
        w.ph = [0] * 3
        w.idle = 0
        w.pair_until = 0
        w.osc, w.osc_fired, w.p2 = 0, False, None
        w.kh_until = 0
        w.score = (0, 0)
        w.act = [0] * 7                                   # mv atk cap chan wait idle dead (turns per tick)
        w.moved = False
        errs = set()
        fu = []
        f0 = fuel()
        trace("env", f"round={cambc.round_number()} fuel_at_start={f0} turn_budget={cambc.constants.FUEL_PER_TURN if hasattr(cambc.constants, 'FUEL_PER_TURN') else '?'}")
        try:
            me_init()                                     # 20_champs: ME facts, once (traces tag me)
            w.boot()
            w.pos = w.fme_root
            seed = opening_seed(w)
            if seed is not None:
                s = sense(w)
                w.set_cur(("farm", seed), s.r, s)
                w.seed_until = s.r + 2                    # everyone writes the seed before anyone re-prices
                trace("choice", f"farm {tname(w, 'farm', seed)} seed slot={w.slot}")
                broadcast(w, s, 1)
        except Exception as e:
            trace("err", "boot " + err_text(e))
        trace("boot", f"round1 fuel={f0 - fuel()} left={fuel()}")
        cambc.end_turn()
        while True:
            f0 = fuel()
            try:
                turn(w)
            except Exception as e:
                t = err_text(e)
                if t not in errs:
                    errs.add(t)
                    trace("err", t)
            used = f0 - fuel()
            fu.append(used)
            r = cambc.round_number()
            if r % 50 == 0:
                try:
                    me = cambc.me()
                    alive = me.is_alive()
                    trace("tick", f"{w.cur[0]} hp={me.health() if alive else 0:.0f} bag={me.gem_count() if alive else 0} "
                                  f"gold={me.gold_count()} fuel={used} fmax={max(fu)} fmed={sorted(fu)[len(fu) // 2]} "
                                  f"pos={w.pos.x},{w.pos.y} act={'/'.join(map(str, w.act))} ph={w.ph} "
                                  f"score={w.score[0]}-{w.score[1]}")
                except Exception as e:
                    trace("err", "tick " + err_text(e))
                fu = []
                w.ph = [0] * 3
                w.act = [0] * 7
            cambc.end_turn()

    play_main()
